recipes.code:
{
  "inputs": [
    {
      "id": "bowmark-api-key",
      "type": "promptString",
      "description": "Optional. A free API key lifts the anonymous per-IP daily cap to your account's monthly plan budget; omit it to use the anonymous tier. Mint a key from the dashboard at https://bowmark.ai.",
      "password": true
    }
  ],
  "servers": {
    "bowmark": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "bowmark-mcp@2.0.0"
      ],
      "env": {
        "BOWMARK_API_KEY": "${input:bowmark-api-key}"
      }
    }
  }
}
